package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdReader;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdResolver;
import com.fasterxml.jackson.databind.deser.impl.PropertyMetadata;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import java.io.*;
import java.io.IOException;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class ObjectIdValueProperty_deserializeSetAndReturn_TriageGen1Test {

    @Mock
    private JsonParser p;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private JsonDeserializer<Object> valueDeserializer;

    @Mock
    private ObjectIdReader objectIdReader;

    @Mock
    private ReadableObjectId roid;

    @Mock
    private SettableBeanProperty idProp;

    @Mock
    private PropertyMetadata metadata;

    private ObjectIdValueProperty target;
    private Object instance;
    private Object idValue;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        instance = new Object();
        idValue = "test-id";

        // Setup ObjectIdReader internal fields via reflection or mock behavior if possible.
        // Since they are accessed directly in the method, we must ensure they are not null.
        // Note: In a real Jackson environment, these are usually set via constructor or reflection.
        // For this test, we assume the fields are accessible or the reader is configured.

        // Mocking the internal structure of ObjectIdReader
        // We use a trick: since we can't easily mock final/private fields of a class without reflection,
        // we rely on the fact that the class is being tested.
        // However, the method accesses _objectIdReader.generator and _objectIdReader.resolver directly.
        // We will use a real ObjectIdReader instance to avoid NullPointerException on field access.

        objectIdReader.generator = mock(com.fasterxml.jackson.databind.DatabindContext.class); // dummy for field access if needed
        // Actually, the code uses: _objectIdReader.generator and _objectIdReader.resolver
        // We will use reflection to inject mocks into the reader if necessary, 
        // but here we'll assume we can provide a mock reader with pre-set fields.

        // Due to the direct field access in the source code, we must ensure the reader is not null.
        // We'll use a mock but we must handle the field access.
        // Since we can't easily mock field access on a mock object in standard Mockito, 
        // we will use a real ObjectIdReader and inject dependencies.

        // Let's try to use a real reader and inject mocks into its fields.
        // But for simplicity in this unit test, we'll mock the Reader and use Mockito's ability 
        // to return values for fields if we were using PowerMock, but since we are using JUnit 4/Mockito,
        // I will simulate the object structure.
    }

    /**
     * Helper to create the target instance with the mocked reader.
     * Because the code accesses _objectIdReader.generator etc. directly, 
     * we need a reader where these fields are not null.
     */
    private ObjectIdValueProperty createTarget() throws Exception {
        ObjectIdValueProperty property = new ObjectIdValueProperty(objectIdReader, metadata);

        // Use reflection to set the private field _valueDeserializer
        java.lang.reflect.Field vDeserField = ObjectIdValueProperty.class.getDeclaredField("_valueDeserializer");
        vDeserField.setAccessible(true);
        vDeserField.set(property, valueDeserializer);

        // Use reflection to set the private field _objectIdReader
        java.lang.reflect.Field oReaderField = ObjectIdValueProperty.class.getDeclaredField("_objectIdReader");
        oReaderField.setAccessible(true);
        oReaderField.set(property, objectIdReader);

        return property;
    }

    @Test
    public void testDeserializeSetAndReturn_ReturnsNullWhenIdIsNull() throws Exception {
        when(valueDeserializer.deserialize(p, ctxt)).thenReturn(null);
        ObjectIdValueProperty target = createTarget();

        Object result = target.deserializeSetAndReturn(p, ctxt, instance);

        assertNull(result);
        verify(valueDeserializer).deserialize(p, ctxt);
        verifyNoInteractions(ctxt);
    }

    @Test
    public void testDeserializeSetAndReturn_WithIdPropNotNull() throws Exception {
        when(valueDeserializer.deserialize(p, ctxt)).thenReturn(idValue);
        when(ctxt.findObjectId(eq(idValue), any(), any())).thenReturn(roid);

        // Setup the reader to have the idProp
        java.lang.reflect.Field idPropField = ObjectIdReader.class.getDeclaredField("idProperty");
        idPropField.setAccessible(true);
        idPropField.set(objectIdReader, idProp);

        // Mocking the generator and resolver to avoid NPE during findObjectId call
        // Although findObjectId is called on ctxt, the arguments passed are from objectIdReader
        // The code accesses: _objectIdReader.generator and _objectIdReader.resolver
        // We need to ensure those fields are not null to avoid NPE in the method itself.
        // Since they are package-private/public in ObjectIdReader:
        // (Assuming standard Jackson structure)

        ObjectIdValueProperty target = createTarget();

        // Mocking the return of idProp.setAndReturn
        Object expectedReturn = "returned-id-value";
        when(idProp.setAndReturn(instance, idValue)).thenReturn(expectedReturn);

        Object result = target.deserializeSetAndReturn(p, ctxt, instance);

        assertEquals(expectedReturn, result);
        verify(roid).bindItem(instance);
        verify(idProp).setAndReturn(instance, idValue);
    }

    @Test
    public void testDeserializeSetAndReturn_WithIdPropNull() throws Exception {
        when(valueDeserializer.deserialize(p, ctxt)).thenReturn(idValue);
        when(ctxt.findObjectId(eq(idValue), any(), any())).thenReturn(roid);

        // Setup the reader to have null idProp
        java.lang.reflect.Field idPropField = ObjectIdReader.class.getDeclaredField("idProperty");
        idPropField.setAccessible(true);
        idPropField.set(objectIdReader, null);

        ObjectIdValueProperty target = createTarget();

        Object result = target.deserializeSetAndReturn(p, ctxt, instance);

        assertEquals(instance, result);
        verify(roid).bindItem(instance);
        verify(idProp, never()).setAndReturn(any(), any());
    }

    @Test(expected = IOException.class)
    public void testDeserializeSetAndReturn_ThrowsIOException() throws Exception {
        when(valueDeserializer.deserialize(p, ctxt)).thenThrow(new IOException("Deserialization failed"));
        ObjectIdValueProperty target = createTarget();

        target.deserializeSetAndReturn(p, ctxt, instance);
    }
}
